#Header #include &#34;co/def.h&#34; #Integer Type Aliases typedef int8_t int8; typedef int16_t int16; typedef int32_t int32; typedef int64_t int64; typedef uint8_t uint8; typedef uint16_t uint16; typedef uint32_t uint32; typedef uint64_t uint64; Defined in the global namespace. #Integer Extreme Value Constants namespace co { constexpr uint8 max_uint8 = (uint8) ~((uint8) 0); constexpr uint16 max_uint16 = (uint16) ~((uint16)0); constexpr uint32 max_uint32 = (uint32) ~((uint32)0); constexpr uint64 max_uint64 = (uint64) ~((uint64)0); constexpr int8 max_int8 = (int8) (max_uint8 &gt;&gt; 1); constexpr int16 max_int16 = (int16) (max_uint16 &gt;&gt; 1); constexpr int32 max_int32 = (int32) (max_uint32 &gt;&gt; 1); constexpr int64 max_int64 = (int64) (max_uint64 &gt;&gt; 1); constexpr int8 min_int8 = (int8) ~max_int8; constexpr int16 min_int16 = (int16) ~max_int16; constexpr int32 min_int32 = (int32) ~max_int32; constexpr int64 min_int64 = (int64) ~max_int64; } // co Defined in the co namespace; all are constexpr. Example:
#include &#34;co/def.h&#34; #include &#34;co/print.h&#34; int main() { co::println(&#34;max_uint32 = &#34;, co::max_uint32); co::println(&#34;max_int32 = &#34;, co::max_int32); co::println(&#34;min_int32 = &#34;, co::min_int32); return 0; } #Cache Line Size Provides the compile-time constant co::cache_line_size, commonly used for memory alignment and avoiding false sharing. Values for each architecture are as follows:
Architecture co::cache_line_size S390X 256 PowerPC64 128 ARM64 128 Others (x86, x64, etc.) 64 co::cache_line_size may be larger than the actual cache line size. When aligning or padding, it will occupy a small amount of extra memory, which usually has little impact. Example:
// Allocate cache-line-aligned memory co::alloc(n, co::cache_line_size); #Macros #Architecture #if SIZE_MAX == UINT64_MAX #define __arch64 1 #elif SIZE_MAX == UINT32_MAX #define __arch32 1 #else #error &#34;platform not supported&#34; #endif On 64-bit platforms, the __arch64 macro is defined with a value of 1; On 32-bit platforms, the __arch32 macro is defined with a value of 1; #Cache Line Alignment #ifndef __cacheline_aligned #define __cacheline_aligned alignas(co::cache_line_size) #endif The __cacheline_aligned macro aligns a variable or struct to a cache line. Example:
struct __cacheline_aligned Foo { int x; }; #Thread-Local Storage #ifdef _MSC_VER #ifndef __thread #define __thread __declspec(thread) #endif #endif __thread is used to define thread-local variables; gcc/clang already have built-in __thread; on Windows (using MSVC), it is defined as __declspec(thread). Example:
__thread int g_v; __thread void* g_p; #__unlikely Hints to the compiler that a condition is more likely to be false. In older versions it was named unlikey; to avoid conflict with C++20 [[unlikely]], it was changed to __unlikely. Example:
fs::file f(&#34;xx.log&#34;, &#39;r&#39;); if (__unlikely(!f)) co::println(&#34;open file failed&#34;);

#Header #include &#34;co/sock.h&#34; The API is in the co namespace. Before use, you need to call flag::parse(argc, argv); at the beginning of main.
sock_t is in the global namespace.
#Overview Coroutine-based socket API. I/O-related APIs do not block the scheduling thread and must be called inside a coroutine. On error, use co::error() / co::strerror() to get error information. #Address co::sockaddr struct sockaddr { sockaddr(); sockaddr(const char* host, uint16 port); bool valid() const; int af() const; }; Supports IPv4, IPv6, and domain name resolution. af() returns AF_INET or AF_INET6. Can be printed directly, in the format 127.0.0.1:8080. #I/O Event Types enum ev_t { ev_read = 1, ev_write = 2, }; Bitwise OR combination is not supported. #Creating a Socket sock_t co::tcp_socket(int af=0); sock_t co::udp_socket(int af=0); sock_t co::tcp_server_socket(const char* host, uint16 port, int backlog=4096); af=0 defaults to AF_INET. The created socket is already non-blocking. tcp_server_socket: creates a TCP socket, binds the address, and listens. #Socket Operations int co::close(sock_t fd, int ms=0); int co::bind(sock_t fd, const sockaddr&amp; addr); int co::listen(sock_t fd, int backlog=4096); int co::connect(sock_t fd, const sockaddr&amp; addr, int ms=-1); sock_t co::accept(sock_t fd, sockaddr* addr=nullptr); close(fd, ms): delays closing by ms milliseconds to prevent malicious attacks. connect: ms=-1 means no timeout; the timeout error code is ETIMEDOUT. accept returns the socket on success and (sock_t)-1 on error; the others return 0 on success and -1 on error. #Send and Receive int co::recv(sock_t fd, void* buf, int n, int ms=-1); int co::recvn(sock_t fd, void* buf, int n, int ms=-1); int co::recvfrom(sock_t fd, void* buf, int n, sockaddr&amp; addr, int ms=-1); int co::send(sock_t fd, const void* buf, int n, int ms=-1); int co::sendto(sock_t fd, const void* buf, int n, const sockaddr&amp; addr, int ms=-1); recv: single read, may return fewer than n bytes. recvn: reads exactly n bytes, suitable for protocols with a fixed-length header. recvfrom: UDP receive; when the function returns, addr is filled with the sender&rsquo;s address. send: returning n on success means all data was sent; the state after an error or timeout is undefined. sendto: UDP send. ms=-1 means no timeout; the timeout error code is ETIMEDOUT. #Socket Options void co::set_reuseaddr(sock_t fd); void co::set_tcp_nodelay(sock_t fd); void co::set_tcp_keepalive(sock_t fd); void co::set_send_buffer_size(sock_t fd, int n); void co::set_recv_buffer_size(sock_t fd, int n); void co::set_nonblock(sock_t fd); void co::set_cloexec(sock_t fd); // non-Windows set_send_buffer_size / set_recv_buffer_size must be called before connecting. #Others int co::reset_tcp_socket(sock_t fd, int ms=0); co::sockaddr co::peeraddr(sock_t fd); reset_tcp_socket: resets the connection without entering timed_wait; generally used on the server side. peeraddr: returns the peer address. #Examples #TCP Client #include &#34;co/co.h&#34; #include &#34;co/sock.h&#34; #include &#34;co/print.h&#34; int main(int argc, char** argv) { flag::parse(argc, argv); go([] { co::sockaddr addr(&#34;127.0.0.1&#34;, 8080); sock_t fd = co::tcp_socket(addr.af()); int r = co::connect(fd, addr, 3000); if (r != 0) { co::println(&#34;connect failed: &#34;, co::strerror()); co::close(fd); return; } const char* msg = &#34;hello&#34;; r = co::send(fd, msg, 5, 3000); co::println(&#34;sent &#34;, r, &#34; bytes&#34;); char buf[128]; r = co::recv(fd, buf, sizeof(buf), 3000); if (r &gt; 0) co::println(&#34;recv: &#34;, co::string(buf, r)); co::close(fd); }); co::sleep(5000); return 0; } #TCP Server #include &#34;co/co.h&#34; #include &#34;co/sock.h&#34; #include &#34;co/print.h&#34; int main(int argc, char** argv) { flag::parse(argc, argv); go([] { sock_t s = co::tcp_server_socket(&#34;0.0.0.0&#34;, 8080); if (s == (sock_t)-1) { co::println(&#34;listen failed: &#34;, co::strerror()); return; } while (true) { co::sockaddr addr; sock_t fd = co::accept(s, &amp;addr); if (fd == (sock_t)-1) break; go([fd, addr] { co::println(&#34;accepted: &#34;, addr); char buf[1024]; int n = co::recvn(fd, buf, 4); if (n == 4) { uint32 body_len = *(uint32*)buf; co::string body; body.resize(body_len); co::recvn(fd, body.data(), body_len); co::println(&#34;body: &#34;, body); } co::close(fd); }); } co::close(s); }); co::sleep(60000); return 0; } #UDP #include &#34;co/co.h&#34; #include &#34;co/sock.h&#34; #include &#34;co/print.h&#34; int main(int argc, char** argv) { flag::parse(argc, argv); go([] { sock_t fd = co::udp_socket(); co::sockaddr addr(&#34;127.0.0.1&#34;, 8080); const char* msg = &#34;ping&#34;; co::sendto(fd, msg, 4, addr, 3000); char buf[128]; co::sockaddr peer; int n = co::recvfrom(fd, buf, sizeof(buf), peer, 3000); if (n &gt; 0) co::print(&#34;recvfrom &#34;, peer, &#34;: &#34;, co::string(buf, n), &#39;\n&#39;); co::close(fd); }); co::sleep(5000); return 0; }

#Header #include &#34;co/time.h&#34; flag::parse is not required.
sleep is in the time namespace; the rest are in the co namespace.
#Current Time co::now struct Now { static int64 ns(); // nanoseconds, may overflow in 2262 static int64 us(); // microseconds static int64 ms(); // milliseconds static co::string str(const char* fmt=&#34;%Y-%m-%d %H:%M:%S&#34;); }; ns() / us() / ms() return Unix epoch timestamps (UTC). str() is based on strftime and returns a local time string. #Monotonic Clock co::mono_time struct MonoTime { static int64 ns(); static int64 us(); static int64 ms(); }; Based on std::chrono::steady_clock. Monotonically increasing, suitable for measuring time differences. #Timer co::timer struct timer { timer(); void restart(); int64 ns() const; int64 us() const; int64 ms() const; }; Records the start point on construction. restart() resets the start point. ns() / us() / ms() return the elapsed time from the start point to now. Based on mono_time. #Sleep time::sleep void time::sleep(uint32 ms); Unit is milliseconds. Thread-level sleep, blocks the current thread. Cannot be used in a coroutine; use co::sleep in coroutines. #Example #include &#34;co/time.h&#34; #include &#34;co/print.h&#34; int main() { co::println(&#34;now.ns() = &#34;, co::now.ns()); co::println(&#34;now.us() = &#34;, co::now.us()); co::println(&#34;now.ms() = &#34;, co::now.ms()); co::println(&#34;now.str() = &#34;, co::now.str()); co::println(&#34;now.str(%Y%m%d) = &#34;, co::now.str(&#34;%Y%m%d&#34;)); co::println(&#34;mono.ns() = &#34;, co::mono_time.ns()); co::println(&#34;mono.us() = &#34;, co::mono_time.us()); co::println(&#34;mono.ms() = &#34;, co::mono_time.ms()); co::timer t; time::sleep(100); co::println(&#34;elapsed ns = &#34;, t.ns()); co::println(&#34;elapsed us = &#34;, t.us()); co::println(&#34;elapsed ms = &#34;, t.ms()); t.restart(); time::sleep(50); co::println(&#34;after restart, ms = &#34;, t.ms()); return 0; }
